{
  "status": "STABLE",
  "core_findings": [
    "All four categories pass the reported execution checks; embedding alignment scores of 0.5061–0.5106 across 2,048 sampled items/category indicate near-zero mean pairwise cosine, without evidence of directional collapse.",
    "Sampled training separation is positive across all categories, but Electronics is weakest: 8.08% wrong ranks and a 0.2431 lower-tenth-percentile margin across 10,317 valid positions, versus 1.61–4.52% wrong ranks across 11,076–15,963 positions in the other categories."
  ],
  "key_implications": [
    "The checked module and ModelView agree, while exported-predictor parity remains unestablished by the supplied records.",
    "Electronics shows weaker separation for low-frequency positives: 14.49% wrong ranks across 1,725 positions versus 2.86% across 4,302 high-frequency positions.",
    "Temporal effect estimates and official validation HR@10 are absent from the supplied values, so neither temporal ranking damage nor validation improvement is established."
  ],
  "evidence": {
    "headline_metrics": {
      "categories_passing_reported_execution_checks": 4,
      "embedding_sample_count_per_category": 2048,
      "Electronics:pos_neg_margin_p10": 0.2431,
      "Electronics:pos_neg_neg_beats_pos_rate": 0.0808
    },
    "brief_metric_read": {
      "embedding_collapse_score": "Near 0.5 means little average directional alignment; recommendation diversity is unmeasured.",
      "pos_neg_margin": "Conditional sampled training separation, not held-out ranking performance.",
      "temporal_sensitivity": "200 users/category are reported, but effect values are omitted; omitted evidence is not a zero effect."
    }
  }
}
